.gemini/settings.json:
{
  "hooks": {
    "BeforeTool": [
      {
        "matcher": "*",
        "hooks": [
          {
            "name": "agentguard",
            "type": "command",
            "command": "agw hook gemini_cli BeforeTool",
            "timeout": 660000
          }
        ]
      }
    ],
    "AfterTool": [
      {
        "matcher": "*",
        "hooks": [
          {
            "name": "agentguard",
            "type": "command",
            "command": "agw hook gemini_cli AfterTool"
          }
        ]
      }
    ],
    "SessionStart": [
      {
        "hooks": [
          {
            "name": "agentguard",
            "type": "command",
            "command": "agw hook gemini_cli SessionStart"
          }
        ]
      }
    ],
    "SessionEnd": [
      {
        "hooks": [
          {
            "name": "agentguard",
            "type": "command",
            "command": "agw hook gemini_cli SessionEnd"
          }
        ]
      }
    ]
  },
  "mcpServers": {
    "agentguard": {
      "httpUrl": "https://agentguard.test/mcp"
    }
  }
}
